/**
 * @name SSRF and Insecure SSL in PyJWKClient
 * @description Traces flow from parameters to network request in jwks_client.py and checks for insecure SSL.
 * @kind path-problem
 * @problem.severity error
 * @id py/jwks-ssrf-ssl
 * @tags security
 *       external/cwe/cwe-918
 *       external/cwe/cwe-295
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters of public methods in PyJWKClient or __init__
    exists(Function f |
      f.getScope().getName() = "PyJWKClient" and
      source.(DataFlow::ParameterNode).getParameter() = f.getArg(_)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Argument to urllib.request.urlopen
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("urllib").getMember("request").getMember("urlopen").getACall() and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SSRF: URL from $@ flows to network request.", source.getNode(), "parameter"
